style.css:
/* Bo góc nhẹ cho ảnh và video trên mọi trang web */
img, video, iframe {
    border-radius: 12px !important;
}

/* Làm mượt thanh cuộn (Scrollbar) theo style tối */
::-webkit-scrollbar {
    width: 8px;
}
::-webkit-scrollbar-track {
    background: #1a1b26;
}
::-webkit-scrollbar-thumb {
    background: #414868;
    border-radius: 10px;
}
